mkdir -p /tmp/recon && cat > /tmp/recon/fetch.py <<'EOF'
import json, time, sys, urllib.request, urllib.error
BASE = "http://localhost:8080"
tok = None
log = []
def get_token():
    global tok
    while True:
        try:
            r = urllib.request.urlopen(urllib.request.Request(BASE + "/token", method="POST", data=b""))
            tok = json.load(r)["token"]; log.append(("token", tok)); return
        except urllib.error.HTTPError as e:
            log.append(("token-err", e.code, dict(e.headers))); handle_wait(e)
def handle_wait(e):
    ra = e.headers.get("Retry-After")
    time.sleep(float(ra) if ra else 1)
def get(path):
    attempts = 0
    while True:
        attempts += 1
        if tok is None: get_token()
        req = urllib.request.Request(BASE + path, headers={"Authorization": "Bearer " + tok})
        try:
            r = urllib.request.urlopen(req, timeout=30)
            body = r.read()
            try:
                return 200, json.loads(body)
            except Exception:
                log.append(("badjson", path, body[:200])); time.sleep(0.5); continue
        except urllib.error.HTTPError as e:
            body = e.read()[:300]
            log.append((path, e.code, e.headers.get("Retry-After"), body))
            if e.code == 401: get_token(); continue
            if e.code == 404: return 404, json.loads(body or b"{}")
            if e.code == 429: handle_wait(e); continue
            handle_wait(e); continue
        except Exception as e:
            log.append((path, "exc", repr(e))); time.sleep(1); continue

pages = {}
s, p1 = get("/orders?page=1"); pages[1] = p1
total = p1["total_pages"]
for n in range(2, total + 1):
    s, p = get(f"/orders?page={n}"); pages[n] = p
    if p.get("total_pages") != total: log.append(("total_pages changed", n, p.get("total_pages")))
# check next chain consistency
for n, p in pages.items():
    exp = f"/orders?page={n+1}" if n < total else None
    if p.get("next") != exp: log.append(("next mismatch", n, p.get("next")))
    if p.get("page") != n: log.append(("page mismatch", n, p.get("page")))
custs = {}
for p in pages.values():
    for o in p["items"]:
        c = o["customer_id"]
        if c not in custs:
            custs[c] = get(f"/customers/{c}")
json.dump({"pages": pages, "custs": custs}, open("/tmp/recon/raw.json", "w"))
json.dump(log, open("/tmp/recon/log.json", "w"), default=str, indent=0)
print("pages", total, "customers", len(custs), "log entries", len(log))
EOF
cd /tmp/recon && python3 -I fetch.py

